INSERT INTO region (public_id, country_id, name_ru, name_kz, name_en, name_uz, slug, is_supported, created_at, updated_at) SELECT seed.public_id, country.id, seed.name_ru, seed.name_ru, seed.name_en, seed.name_uz, seed.slug, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM country CROSS JOIN (VALUES ('06UZRG00000000000000000001', 'город Ташкент', 'Tashkent City', 'Toshkent shahri', 'tashkent-city'), ('06UZRG00000000000000000002', 'Республика Каракалпакстан', 'Republic of Karakalpakstan', 'Qoraqalpog‘iston Respublikasi', 'karakalpakstan'), ('06UZRG00000000000000000003', 'Андижанская область', 'Andijan Region', 'Andijon viloyati', 'andijan-region'), ('06UZRG00000000000000000004', 'Бухарская область', 'Bukhara Region', 'Buxoro viloyati', 'bukhara-region'), ('06UZRG00000000000000000005', 'Джизакская область', 'Jizzakh Region', 'Jizzax viloyati', 'jizzakh-region'), ('06UZRG00000000000000000006', 'Кашкадарьинская область', 'Kashkadarya Region', 'Qashqadaryo viloyati', 'kashkadarya-region'), ('06UZRG00000000000000000007', 'Навоийская область', 'Navoi Region', 'Navoiy viloyati', 'navoi-region'), ('06UZRG00000000000000000008', 'Наманганская область', 'Namangan Region', 'Namangan viloyati', 'namangan-region'), ('06UZRG00000000000000000009', 'Самаркандская область', 'Samarkand Region', 'Samarqand viloyati', 'samarkand-region'), ('06UZRG00000000000000000010', 'Сурхандарьинская область', 'Surkhandarya Region', 'Surxondaryo viloyati', 'surkhandarya-region'), ('06UZRG00000000000000000011', 'Сырдарьинская область', 'Syrdarya Region', 'Sirdaryo viloyati', 'syrdarya-region'), ('06UZRG00000000000000000012', 'Ташкентская область', 'Tashkent Region', 'Toshkent viloyati', 'tashkent-region'), ('06UZRG00000000000000000013', 'Ферганская область', 'Fergana Region', 'Farg‘ona viloyati', 'fergana-region'), ('06UZRG00000000000000000014', 'Хорезмская область', 'Khorezm Region', 'Xorazm viloyati', 'khorezm-region') ) AS seed(public_id, name_ru, name_en, name_uz, slug) WHERE country.code = 'UZ' ON 